import re

html = open("/dev/stdin").read()

tickers = []
for match in re.finditer(r'<a[^>]*href=["\']/wiki/([A-Z]{1,5})["\']', html):
    tickers.append(match.group(1))

seen = set()
unique_tickers = []
for t in tickers:
    if t not in seen:
        seen.add(t)
        unique_tickers.append(t)

print(f"Found {len(unique_tickers)} tickers")
for t in unique_tickers:
    print(t)
